function validate([nums, k, x]) {
  if (nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some((v) => !Number.isInteger(v) || v < 1 || v > 50)) return 'Each value of nums is a whole number from 1 to 50.';
  if (!Number.isInteger(k) || !Number.isInteger(x) || x < 1 || x > k || k > nums.length) return 'k and x must satisfy 1 <= x <= k <= nums.length.';
  return null;
}

