function findXSum(nums, k, x) {
  const count = new Map();
  const answer = [];
  for (let right = 0; right < nums.length; right++) {
    count.set(nums[right], (count.get(nums[right]) ?? 0) + 1);
    const left = right - k + 1;
    if (left < 0) {
      continue;
    }
    const ranked = [...count].sort((a, b) => b[1] - a[1] || b[0] - a[0]);
    let sum = 0;
    for (const [value, times] of ranked.slice(0, x)) {
      sum += value * times;
    }
    answer.push(sum);
    count.set(nums[left], count.get(nums[left]) - 1);
    if (count.get(nums[left]) === 0) {
      count.delete(nums[left]);
    }
  }
  return answer;
}

