function findXSum(nums, k, x) {
  // Recount each window from scratch, then pick the most frequent value x times, the larger one on ties.
  const result = [];
  for (let i = 0; i + k <= nums.length; i++) {
    const freq = new Array(51).fill(0);
    for (let j = i; j < i + k; j++) freq[nums[j]]++;
    let total = 0;
    for (let round = 0; round < x; round++) {
      let pick = 0;
      // Scanning upward with >= lets a larger value take over an equal tally.
      for (let v = 1; v <= 50; v++) if (freq[v] > 0 && freq[v] >= freq[pick]) pick = v;
      if (pick === 0) break;
      total += pick * freq[pick];
      freq[pick] = 0;
    }
    result.push(total);
  }
  return result;
}

