function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 50 : 1 + Math.floor(rand() * 10);
  // A narrow range of values gives repeats and tied tallies; a wide one gives many distinct values.
  const span = [2, 3, 4, 6, 10, 50][Math.floor(rand() * 6)];
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * span));
  if (rand() < 0.2) nums[Math.floor(rand() * n)] = 50;
  const k = 1 + Math.floor(rand() * n);
  const x = 1 + Math.floor(rand() * k);
  return [nums, k, x];
}
